#!/usr/bin/env python3
"""Regenerates the eggs. egg-phreox-service.json embeds install.sh, the backend and web eggs embed update.sh: edit those and run this script."""
import json
from pathlib import Path

here = Path(__file__).parent
script = (here / "install.sh").read_text()


def variable(name, description, env, default, rules, viewable=True):
    return {"name": name, "description": description, "env_variable": env, "default_value": default,
            "user_viewable": viewable, "user_editable": True, "rules": rules, "field_type": "text"}


egg = {
    "_comment": "DO NOT EDIT: FILE GENERATED BY pterodactyl/build-egg.py",
    "meta": {"version": "PTDL_v2", "update_url": None},
    "exported_at": "2026-11-06T00:00:00+00:00",
    "name": "Phreox Service",
    "author": "admin@bluenet-hosting.com",
    "description": "phreox-service, the account, friends, DM and presence server of Phreox. A supervisor checks the releases repository "
                   "every 30 seconds and updates the server without a gap: the new version listens next to the old one on the same port, "
                   "then the old one finishes its requests and stops.",
    "features": None,
    "docker_images": {"Java 25": "ghcr.io/pterodactyl/yolks:java_25"},
    "file_denylist": [],
    # The supervisor only waits and asks GitHub: it gets a tiny JVM of its own, the service a small one (see PHREOX_JAVA_OPTS).
    "startup": "java -XX:+UseSerialGC -Xms8m -Xmx32m -Xss256k -XX:TieredStopAtLevel=1 -XX:CICompilerCount=1 -XX:-UsePerfData -XX:ReservedCodeCacheSize=16m -XX:MaxMetaspaceSize=64m -cp supervisor.jar talk.phreox.service.supervisor.Supervisor",
    "config": {"files": "{}", "startup": json.dumps({"done": "Phreox supervisor: service is up"}), "logs": "{}", "stop": "^C"},
    "scripts": {"installation": {"script": script, "container": "ghcr.io/ptero-eggs/installers:debian", "entrypoint": "bash"}},
    "variables": [
        variable("Update channel", "Which releases this server follows: release (stable), beta (beta, pre, rc), alpha or dev. The server only takes releases of its own channel.",
                 "PHREOX_UPDATE_CHANNEL", "release", "required|string|in:release,beta,alpha,dev"),
        variable("Releases repository", "GitHub repository the releases are published to.",
                 "PHREOX_UPDATE_REPO", "Phreox/releases", "required|string|regex:/^[A-Za-z0-9_.-]+\\/[A-Za-z0-9_.-]+$/"),
        variable("GitHub token", "Token with read access to the contents of the releases repository. Needed while that repository is private.",
                 "PHREOX_UPDATE_TOKEN", "", "nullable|string|max:255", False),
        variable("Update interval (seconds)", "How often the releases are checked. A check that finds nothing new costs no API quota.",
                 "PHREOX_UPDATE_INTERVAL_SECONDS", "30", "required|integer|between:5,3600"),
        variable("Admin token", "Secret of the operator, at least 32 characters. Only a node that presents it may use a reserved domain, and entitlements can only be granted with it.",
                 "PHREOX_SERVICE_ADMIN_TOKEN", "", "nullable|string|min:32|max:255", False),
        variable("Reserved domains", "Comma separated domains that ordinary accounts cannot register nodes for.",
                 "PHREOX_SERVICE_RESERVED_DOMAINS", "phreox.talk", "nullable|string|max:255"),
        variable("Klipy key", "Klipy app key for the GIF search. Without it the service offers no GIFs.",
                 "PHREOX_KLIPY_KEY", "", "nullable|string|max:255", False),
        variable("Java options", "Options of the JVM that runs the service. The default keeps it small: serial collector, 192 MB heap at most, one compiler thread.",
                 "PHREOX_JAVA_OPTS", "-XX:+UseSerialGC -Xms16m -Xmx192m -Xss256k -XX:MaxMetaspaceSize=96m -XX:ReservedCodeCacheSize=24m -XX:TieredStopAtLevel=1 -XX:CICompilerCount=1 -XX:-UsePerfData -XX:+ExitOnOutOfMemoryError", "required|string|max:255"),
    ],
}

(here / "egg-phreox-service.json").write_text(json.dumps(egg, indent=2, ensure_ascii=False) + "\n")
print("egg-phreox-service.json:", len(egg["variables"]), "variables")


# ---- the backend server (backend.phreox.talk) and the web version (phreox.talk) ----

update_script = (here / "update.sh").read_text()
channel = variable("Update channel", "Which releases this server follows: release (stable), beta (beta, pre, rc), alpha or dev. The server only takes releases of its own channel.",
                   "PHREOX_UPDATE_CHANNEL", "release", "required|string|in:release,beta,alpha,dev")
repository = variable("Releases repository", "GitHub repository the releases are published to.",
                      "PHREOX_UPDATE_REPO", "Phreox/releases", "required|string|regex:/^[A-Za-z0-9_.-]+\\/[A-Za-z0-9_.-]+$/")
token = variable("GitHub token", "Token with read access to the contents of the releases repository. Needed while that repository is private.",
                 "PHREOX_UPDATE_TOKEN", "", "nullable|string|max:255", False)


def installer(artifact):
    # The installer writes the update script next to the server and runs it once; the start command runs it before every start.
    return f"#!/bin/bash\nset -euo pipefail\ncd /mnt/server\ncat > update.sh <<'PHREOX_UPDATE'\n{update_script}\nPHREOX_UPDATE\nchmod +x update.sh\nPHREOX_ARTIFACT={artifact} bash update.sh\n"


def write(file, egg):
    egg["author"] = egg_author
    (here / file).write_text(json.dumps(egg, indent=2, ensure_ascii=False) + "\n")
    print(file + ":", len(egg["variables"]), "variables")


egg_author = egg["author"]

write("egg-phreox-backend.json", {
    "_comment": "DO NOT EDIT: FILE GENERATED BY pterodactyl/build-egg.py",
    "meta": {"version": "PTDL_v2", "update_url": None},
    "exported_at": "2026-11-06T00:00:00+00:00",
    "name": "Phreox Backend",
    "description": "phreox-backend as a server (backend.phreox.talk): the backend that the web version of Phreox talks to. It takes the newest release of its "
                   "channel at installation and at every start, and is reached with an address and a token.",
    "features": None,
    "docker_images": {"Java 25": "ghcr.io/pterodactyl/yolks:java_25"},
    "file_denylist": [],
    "startup": "PHREOX_ARTIFACT=backend bash update.sh; PHREOX_BRIDGE_PORT={{SERVER_PORT}} PHREOX_DATA_DIR=/home/container/data java {{PHREOX_JAVA_OPTS}} -jar phreox-backend.jar",
    "config": {"files": "{}", "startup": json.dumps({"done": "Phreox backend"}), "logs": "{}", "stop": "^C"},
    "scripts": {"installation": {"script": installer("backend"), "container": "ghcr.io/ptero-eggs/installers:debian", "entrypoint": "bash"}},
    "variables": [
        channel, repository, token,
        variable("Bridge token", "Secret that everyone needs who uses this backend, at least 32 characters. Whoever has it acts as the signed-in account: keep it secret.",
                 "PHREOX_BRIDGE_TOKEN", "", "required|string|min:32|max:255", False),
        variable("Local key", "32 random bytes as Base64 (openssl rand -base64 32). Secrets of the backend are encrypted with it; without it nothing secret is stored.",
                 "PHREOX_LOCAL_KEY", "", "nullable|string|max:255", False),
        variable("Allowed origins", "Comma separated origins of the web apps that may use this backend.",
                 "PHREOX_BRIDGE_ORIGINS", "https://phreox.talk", "required|string|max:500"),
        variable("Allowed hosts", "Comma separated host names (with the port if it is not 80/443) under which this backend is reached.",
                 "PHREOX_BRIDGE_HOSTS", "backend.phreox.talk", "required|string|max:500"),
        variable("Bind address", "Address to listen on. In a container it has to be 0.0.0.0.",
                 "PHREOX_BRIDGE_BIND", "0.0.0.0", "required|string|max:64"),
        variable("Service servers", "Comma separated addresses of the Phreox service, highest priority first.",
                 "PHREOX_SERVICE_URLS", "https://service.phreox.talk", "required|string|max:500"),
        variable("Environment", "PRODUCTION, BETA, INTERNAL, REMOTE_DEV or LOCAL_DEV. It selects the database file; the two dev values also allow plain http to the service.",
                 "PHREOX_ENV", "PRODUCTION", "required|string|in:PRODUCTION,BETA,INTERNAL,REMOTE_DEV,LOCAL_DEV"),
        variable("Java options", "Options of the JVM that runs the backend.",
                 "PHREOX_JAVA_OPTS", "-XX:+UseG1GC -XX:MaxGCPauseMillis=50 -XX:G1PeriodicGCInterval=60000 -Xms32m -Xmx512m -XX:+ExitOnOutOfMemoryError", "required|string|max:255"),
    ],
})

write("egg-phreox-web.json", {
    "_comment": "DO NOT EDIT: FILE GENERATED BY pterodactyl/build-egg.py",
    "meta": {"version": "PTDL_v2", "update_url": None},
    "exported_at": "2026-11-06T00:00:00+00:00",
    "name": "Phreox Web",
    "description": "The web version of Phreox (phreox.talk): the built app, served by a small Node server. It takes the newest release of its channel at "
                   "installation and at every start. The app asks for the address of a backend server (backend.phreox.talk).",
    "features": None,
    "docker_images": {"Node 22": "ghcr.io/pterodactyl/yolks:nodejs_22"},
    "file_denylist": [],
    "startup": "PHREOX_ARTIFACT=web bash update.sh; node web/server.mjs",
    "config": {"files": "{}", "startup": json.dumps({"done": "Phreox web: listening"}), "logs": "{}", "stop": "^C"},
    "scripts": {"installation": {"script": installer("web"), "container": "ghcr.io/ptero-eggs/installers:debian", "entrypoint": "bash"}},
    "variables": [channel, repository, token],
})
